# Generated by Sanka. Async FastAPI over the existing SQL tables.
from contextlib import asynccontextmanager

from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse, Response
from starlette.convertors import Convertor, register_url_convertor
from starlette.middleware.httpsredirect import HTTPSRedirectMiddleware
from starlette.middleware.trustedhost import TrustedHostMiddleware

import sanka_native as native
import sanka_store as store


@asynccontextmanager
async def lifespan(_app: FastAPI):
    await store.init_db()
    try:
        yield
    finally:
        await store.close_db()


app = FastAPI(title="Sanka native FastAPI application", lifespan=lifespan)

_DJANGO_DEFAULT_404 = "\n<!doctype html>\n<html lang=\"en\">\n<head>\n  <title>Not Found</title>\n</head>\n<body>\n  <h1>Not Found</h1><p>The requested resource was not found on this server.</p>\n</body>\n</html>\n"

@app.exception_handler(404)
async def django_default_404(_request: Request, _error: Exception) -> HTMLResponse:
    return HTMLResponse(_DJANGO_DEFAULT_404, status_code=404)

_HTTP_SECURITY = native.MANIFEST.get("http_security", {})
_ALLOWED_HOSTS = _HTTP_SECURITY.get("allowed_hosts", [])
if _HTTP_SECURITY.get("ssl_redirect"):
    app.add_middleware(HTTPSRedirectMiddleware)
if _ALLOWED_HOSTS and "*" not in _ALLOWED_HOSTS:
    app.add_middleware(TrustedHostMiddleware, allowed_hosts=_ALLOWED_HOSTS)

@app.middleware("http")
async def add_security_headers(request: Request, call_next):
    response = await call_next(request)
    native.apply_security_headers(response, request, _HTTP_SECURITY)
    return response

class _SankaWidgetLookupConvertor(Convertor):
    regex = "[^/.]+"

    def convert(self, value: str) -> str:
        return value

    def to_string(self, value: str) -> str:
        return value


register_url_convertor("sanka_widget_lookup", _SankaWidgetLookupConvertor())

_WIDGET = native.resource("widgets.views.WidgetViewSet")

@app.get("/api/")
async def api_root(request: Request) -> Response:
    return await native.api_root(request, "/api/")

@app.get("/api/widgets/")
async def list_widget(request: Request) -> Response:
    return await native.handle(_WIDGET, "list", request)

@app.post("/api/widgets/")
async def create_widget(request: Request) -> Response:
    return await native.handle(_WIDGET, "create", request)

@app.delete("/api/widgets/{pk:sanka_widget_lookup}/")
async def delete_widget(request: Request, pk: str) -> Response:
    return await native.handle(_WIDGET, "destroy", request)

@app.get("/api/widgets/{pk:sanka_widget_lookup}/")
async def get_widget(request: Request, pk: str) -> Response:
    return await native.handle(_WIDGET, "retrieve", request)

@app.patch("/api/widgets/{pk:sanka_widget_lookup}/")
async def update_widget(request: Request, pk: str) -> Response:
    return await native.handle(_WIDGET, "partial_update", request)

@app.put("/api/widgets/{pk:sanka_widget_lookup}/")
async def replace_widget(request: Request, pk: str) -> Response:
    return await native.handle(_WIDGET, "update", request)

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=8000)
